class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        # Start at position 0 (top-left corner)
        row, col = 0, 0

        # Process each command
        for command in commands:
            if command == "RIGHT":
                col += 1
            elif command == "LEFT":
                col -= 1
            elif command == "DOWN":
                row += 1
            elif command == "UP":
                row -= 1

        # Convert final (row, col) position back to grid position
        # position = row * n + col
        return row * n + col

class Solution:
    def winningPlayerCount(self, n: int, pick: List[List[int]]) -> int:
        # Dictionary to store count of balls of each color for each player
        player_color_count = {}

        # Initialize for all players
        for i in range(n):
            player_color_count[i] = {}

        # Count balls for each player
        for player, color in pick:
            if color not in player_color_count[player]:
                player_color_count[player][color] = 0
            player_color_count[player][color] += 1

        # Count winning players
        winning_count = 0

        # Check each player from 0 to n-1
        for player in range(n):
            # Find maximum count of any single color for this player
            max_count = 0
            for color, count in player_color_count[player].items():
                max_count = max(max_count, count)

            # Player i wins if they have at least (i+1) balls of the same color
            if max_count >= player + 1:
                winning_count += 1

        return winning_count

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        # Calculate minimum flips needed to make all rows palindromic
        min_flips_rows = 0
        for i in range(m):
            # For each row, check symmetric pairs
            for j in range(n // 2):
                # Compare position j with position (n-1-j)
                if grid[i][j] != grid[i][n - 1 - j]:
                    min_flips_rows += 1

        # Calculate minimum flips needed to make all columns palindromic
        min_flips_cols = 0
        for j in range(n):
            # For each column, check symmetric pairs
            for i in range(m // 2):
                # Compare position i with position (m-1-i)
                if grid[i][j] != grid[m - 1 - i][j]:
                    min_flips_cols += 1

        # Return the minimum of both options
        return min(min_flips_rows, min_flips_cols)

